5aac2cb0-dcc4-4d9c-ae07-e57ad34ee429.content:
У меня стоит шаблон "Простор". В этом проекте мы с тобой обсуждали его и работали с ним. В Простор - Настройки шаблона - Общие - Для разработчиков - Пользовательские скрипты у меня вот такой css код: "/* Единая ширина контейнера на весь сайт */
@media (min-width:1199px){
  .container,
  .container-fluid{
    max-width:1350px !important;
  }
}

/* Если конкретную секцию нужно сузить */
@media (min-width:1199px){
  .reviews-featured .container{
    max-width:1000px !important;
  }
}

/* ===== Поиск, кабинет, корзина - один цвет с пунктами меню ===== */
.header__nav-menu > li > a,
.header__search-compact-btn,
.header__acc-btn,
.header__action-btn,
.header__nav-action-btn,
.header__cart-btn,
.header__sticky-btn{color:#2a222b;}
.header__search-compact-btn svg,
.header__acc-btn svg,
.header__action-btn svg,
.header__nav-action-btn svg,
.header__cart-btn svg,
.header__sticky-btn svg{fill:currentColor !important;}

.header__row--02{min-height:120px;}

/* ===== Пункты меню в 1.5 раза крупнее ===== */
.header__nav-menu > li > a{font-size:1.3em;}

/* === Увеличение логотипа === */
/* Десктоп */
@media (min-width:1199px){
  .header__logo{height:12rem !important}
  .header__logo img,.header__logo svg{max-height:10rem !important;max-width:30rem !important;width:auto !important;height:auto !important}
  .is-header-fixed .header-fixed .header__logo{height:8rem !important;flex:0 0 auto !important}
  .is-header-fixed .header-fixed .header__logo img,.is-header-fixed .header-fixed .header__logo svg{max-height:7rem !important;max-width:30rem !important}
}
/* Мобильная версия */
@media (max-width:1199px){
  .header__mobile{height:10rem !important}
  .header__mobile-fixed{height:10rem !important}
  .header__logo img,.header__logo svg{max-height:calc(100% - 2rem) !important;max-width:30rem !important;width:auto !important;height:auto !important}
}

/* ===== Убираем Сравнение товаров везде ===== */
a[href*="compare"],
.header__action-line,
.header__nav-action-line{display:none !important;}

/* Убираем иконку «Избранное» (сердечко) в шапке */
.header__action-btn[href*="wishlist"],
.header__action-btn:has(.icon-favorites){
  display:none !important;
}

/* ===== Брендовые токены Цветочной поэзии ===== */
:root{
--theme-primary-color:#ce2094;
--theme-secondary-color:#a81577;
--cp-bg:#f6f4f5;--cp-paper:#fdfcfd;--cp-ink:#2a222b;--cp-muted:#6d6269;
--cp-pink2:#eebed6;--cp-powder:#f2e3ec;--cp-plum:#6d4a63;
--cp-mint:#b3cebe;--cp-sage:#8ba58e;--cp-gd:#41584a;--cp-mintbg:#e9f2ec;
--cp-line:rgba(42,34,43,.14);
}
html{scroll-behavior:smooth}
body{background:var(--cp-bg);color:var(--cp-ink)}
::selection{background:var(--cp-pink2);color:var(--cp-ink)}
a:focus-visible,button:focus-visible,.ui-btn:focus-visible,input:focus-visible{outline:2px solid var(--cp-acc,#ce2094);outline-offset:2px}

/* ===== Типографика бренда ===== */
h1,h2,h3,h1 a,h2 a,h3 a{font-family:"Cormorant Garamond",Georgia,serif;color:var(--cp-ink)}

/* ===== Шапка (header v4) ===== */
.header{background:rgba(253,252,253,.96)}
.header__row--01{background:var(--cp-mintbg)}
.header__row--01 a,.header__call-btn mark{color:var(--cp-gd)}
.header__nav-menu>li>a{font-weight:500;color:var(--cp-ink)}
.header__nav-menu>li>a:hover{color:var(--cp-accd,#a81577)}
.header__catalog-btn{background:var(--cp-acc,#ce2094);border-radius:999px}

/* ===== Кнопки ===== */
.ui-btn--primary{background:var(--cp-acc,#ce2094);border-color:var(--cp-acc,#ce2094)}
.ui-btn--primary:hover{background:var(--cp-accd,#a81577);border-color:var(--cp-accd,#a81577)}

/* ===== Карточки товаров ===== */
.products__item{background:var(--cp-paper);border:1px solid var(--cp-line);border-radius:24px}

/* ===== Фирменные классы для HTML-блоков (текстовый блок, промо блок) ===== */
.cp-arch{border-radius:999px 999px 28px 28px;overflow:hidden}
.cp-hand{font-family:"Caveat",cursive;color:var(--cp-gd)}
.cp-quote{font-family:"Cormorant Garamond",Georgia,serif;font-style:italic;color:var(--cp-acc,#ce2094);border-left:3px solid var(--cp-mint);padding-left:22px}
.cp-chip{display:inline-block;border-radius:999px;background:var(--cp-powder);color:var(--cp-plum);padding:10px 20px;font-weight:500;margin:0 10px 10px 0}
.cp-chip:hover{background:var(--cp-acc,#ce2094);color:#fff}
.cp-mint-band{background:var(--cp-mintbg);border-radius:32px;padding:48px}
.cp-powder-band{background:var(--cp-powder);border-radius:32px;padding:48px}
.cp-marquee{background:var(--cp-powder);border-top:1px solid var(--cp-line);border-bottom:1px solid var(--cp-line);overflow:hidden;padding:14px 0}
.cp-marquee-track{display:flex;gap:48px;width:max-content;animation:cp-slide 32s linear infinite}
.cp-marquee span{display:flex;gap:48px;white-space:nowrap;font-family:"Cormorant Garamond",Georgia,serif;font-style:italic;font-size:18px;color:var(--cp-plum)}
@keyframes cp-slide{to{transform:translateX(-50%)}}
@media (prefers-reduced-motion:reduce){.cp-marquee-track{animation:none}}

/* ===== ПОДКЛЮЧЕНИЕ ШРИФТОВ ===== */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Jost:wght@400;500;600;700&family=Caveat:wght@500;600&display=swap');

/* ===== HERO СЕКЦИЯ ===== */
.cp-hero {
  position: relative;
  padding: 40px 0; /* Уменьшено с 80px до 40px */
  background: #f6f4f5;
  overflow: hidden;
}

.cp-hero .container {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 56px;
  align-items: center;
  padding: 0 80px; /* Увеличены боковые отступы */
  max-width: 1350px; /* Увеличена максимальная ширина */
  margin: 0 auto;
}

/* Явно задаем порядок для десктопа */
.cp-hero-content {
  order: 1;
}

.cp-hero-image-wrap {
  order: 2;
}

/* ===== ЗАГОЛОВОК ===== */
.cp-hero-title {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 64px;
  font-weight: 600;
  line-height: 1.08;
  color: #2a222b;
  margin: 0 0 24px 0;
  letter-spacing: 0.005em;
}

/* Курсивный акцент в заголовке */
.cp-hero-title em {
  font-style: italic;
  font-weight: 500;
  color: #ce2094;
  padding-bottom: 0.08em;
}

/* ===== ПОДЗАГОЛОВОК ===== */
.cp-hero-subtitle {
  font-family: 'Jost', sans-serif;
  font-size: 17px;
  font-weight: 400;
  line-height: 1.6;
  color: #6d6269;
  margin: 0 0 32px 0;
  max-width: 480px;
}

/* ===== КНОПКИ ===== */
.cp-hero-buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Основная кнопка "Выбрать букет" */
.cp-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 16px 32px;
  background: #ce2094;
  color: #ffffff;
  font-family: 'Jost', sans-serif;
  font-size: 16px;
  font-weight: 600;
  text-decoration: none;
  border-radius: 999px;
  border: 2px solid #ce2094;
  transition: all 0.2s ease;
  box-shadow: 0 12px 28px -12px rgba(206, 32, 148, 0.5);
}

.cp-btn-primary:hover {
  background: #a81577;
  border-color: #a81577;
  transform: translateY(-2px);
  box-shadow: 0 16px 32px -12px rgba(206, 32, 148, 0.6);
  color: #ffffff;
  text-decoration: none;
}

/* Вторичная кнопка "Условия доставки" */
.cp-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 16px 32px;
  background: #f2e3ec;
  color: #6d4a63;
  font-family: 'Jost', sans-serif;
  font-size: 16px;
  font-weight: 600;
  text-decoration: none;
  border-radius: 999px;
  border: 2px solid transparent;
  transition: all 0.2s ease;
}

.cp-btn-secondary:hover {
  background: #ce2094;
  color: #ffffff;
  transform: translateY(-2px);
  text-decoration: none;
}

/* ===== АРХ-ИЗОБРАЖЕНИЕ ===== */
.cp-hero-image-wrap {
  position: relative;
  max-width: 480px; /* Ограничена максимальная ширина изображения */
  margin-left: auto; /* Центрирование */
}

.cp-arch {
  border-radius: 999px 999px 28px 28px;
  overflow: hidden;
  aspect-ratio: 4/5;
  box-shadow: 0 20px 40px -18px rgba(42, 34, 43, 0.16);
}

.cp-arch img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ===== РУКОПИСНАЯ ПОДПИСЬ ===== */
.cp-handwritten {
  position: absolute;
  left: 8px;
  bottom: -10px;
  transform: rotate(-4deg);
  font-family: 'Caveat', cursive;
  font-size: 22px;
  font-weight: 500;
  color: #41584a;
  background: #ffffff;
  padding: 8px 16px;
  border-radius: 999px;
  box-shadow: 0 4px 12px -4px rgba(0, 0, 0, 0.1);
  z-index: 10;
}

/* ===== АДАПТИВ ===== */
@media (max-width: 1199px) {
  .cp-hero .container {
    padding: 0 50px; /* Адаптивные боковые отступы */
  }
}

@media (max-width: 991px) {
  .cp-hero {
    padding: 32px 0; /* Ещё меньше на планшетах */
  }

  .cp-hero .container {
    grid-template-columns: 1fr;
    gap: 40px;
    padding: 0 24px;
  }

  .cp-hero-title {
    font-size: 48px;
  }

  .cp-hero-image-wrap {
    order: -1; /* На мобильном изображение сверху */
    max-width: 360px; /* Меньше изображение на планшетах */
    margin: 0 auto;
  }

  .cp-hero-content {
    order: 2; /* На мобильном текст снизу */
  }
}

@media (max-width: 575px) {
  .cp-hero {
    padding: 24px 0; /* Минимальные отступы на мобильных */
  }

  .cp-hero .container {
    padding: 0 16px;
  }

  .cp-hero-title {
    font-size: 36px;
  }

  .cp-hero-subtitle {
    font-size: 15px;
  }

  .cp-btn-primary,
  .cp-btn-secondary {
    padding: 14px 24px;
    font-size: 15px;
  }

  .cp-hero-image-wrap {
    max-width: 280px; /* Ещё меньше на мобильных */
  }
}



/* ===== СТИЛИЗАЦИЯ БЛОКА ПРЕИМУЩЕСТВ ===== */
.benefits {
    padding: 4rem 0;
    background: var(--color-2);
    overflow: hidden;
}

.benefits__marquee {
    position: relative;
    display: flex;
    overflow: hidden;
    user-select: none;
}

.benefits__track {
    display: flex;
    gap: 4rem;
    animation: scroll 30s linear infinite;
    flex-shrink: 0;
}

.benefits__track:hover {
    animation-play-state: paused;
}

@keyframes scroll {
    0% {
        transform: translateX(0);
    }
    100% {
        transform: translateX(-50%);
    }
}

.benefits__item {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
    min-width: 320px;
    padding: 2rem;
    background: #fff;
    border-radius: 12px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.benefits__icon {
    flex-shrink: 0;
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--color-1);
    border-radius: 50%;
    color: var(--color-4);
}

.benefits__content {
    flex: 1;
}

.benefits__title {
    font-size: 1.6rem;
    font-weight: 600;
    color: var(--color-text);
    margin: 0 0 0.5rem 0;
    line-height: 1.3;
}

.benefits__text {
    font-size: 1.4rem;
    color: var(--color-gray);
    margin: 0;
    line-height: 1.4;
}

@media (max-width: 768px) {
    .benefits {
        padding: 3rem 0;
    }

    .benefits__track {
        gap: 2rem;
        animation-duration: 20s;
    }

    .benefits__item {
        min-width: 280px;
        padding: 1.5rem;
        gap: 1rem;
    }

    .benefits__icon {
        width: 40px;
        height: 40px;
    }

    .benefits__title {
        font-size: 1.4rem;
    }

    .benefits__text {
        font-size: 1.3rem;
    }
}


/* ============================================
   Бегущая строка · Цветочная поэзия
   ============================================ */

.cp-marquee {
  position: relative;
  width: 100%;
  overflow: hidden;
  background: #f2e3ec;              /* пудровый фон */
  border-top: 1px solid rgba(42, 34, 43, 0.14);
  border-bottom: 1px solid rgba(42, 34, 43, 0.14);
  padding: 16px 0;
  -webkit-mask-image: linear-gradient(
    to right,
    transparent 0,
    #000 80px,
    #000 calc(100% - 80px),
    transparent 100%
  );
  mask-image: linear-gradient(
    to right,
    transparent 0,
    #000 80px,
    #000 calc(100% - 80px),
    transparent 100%
  );
}

.cp-marquee__track {
  display: flex;
  width: max-content;
  will-change: transform;
  animation: cp-marquee-scroll 36s linear infinite;
}

.cp-marquee__content {
  display: flex;
  flex-shrink: 0;
  gap: 56px;                      /* расстояние между словами */
  align-items: center;
  list-style: none;
  margin: 0;
  padding: 0 28px;                /* половина от gap для идеального бесшовного стыка */
  counter-reset: marquee;
}

.cp-marquee__content li {
  display: inline-flex;
  align-items: center;
  gap: 12px;                      /* отступ между текстом и точкой */
  white-space: nowrap;
  font-family: 'Cormorant Garamond', serif;
  font-style: italic;
  font-size: 22px;
  font-weight: 600;
  line-height: 1.6;
  letter-spacing: normal;
  color: #6d4a63;                 /* сливовый */
}

/* Разделитель-точка между элементами */
.cp-marquee__content li:not(:last-child)::after {
  content: '';
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #6d4a63;            /* сливовый акцент */
  flex-shrink: 0;
}

/* Пауза при наведении */
.cp-marquee:hover .cp-marquee__track {
  animation-play-state: paused;
}

/* Keyframes: сдвигаем на -50% (один дубликат) для бесшовного цикла */
@keyframes cp-marquee-scroll {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ============================================
   Адаптив
   ============================================ */
@media (max-width: 768px) {
  .cp-marquee {
    padding: 14px 0;
    -webkit-mask-image: linear-gradient(
      to right,
      transparent 0,
      #000 24px,
      #000 calc(100% - 24px),
      transparent 100%
    );
    mask-image: linear-gradient(
      to right,
      transparent 0,
      #000 24px,
      #000 calc(100% - 24px),
      transparent 100%
    );
  }

  .cp-marquee__content {
    gap: 40px;
    padding: 0 20px;
  }

  .cp-marquee__content li {
    font-size: 16px;              /* адаптация для мобильных экранов */
    gap: 8px;
  }

  .cp-marquee__track {
    animation-duration: 24s;
  }
}

/* ============================================
   Respect prefers-reduced-motion
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  .cp-marquee__track {
    animation: none;
  }
  /* Показываем только один набор, чтобы не было дублей */
  .cp-marquee__content[aria-hidden="true"] {
    display: none;
  }
  .cp-marquee__track {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
  }
  .cp-marquee__track::-webkit-scrollbar {
    display: none;
  }
}
/* НАСТРОЙКА ЗАГОЛОВКОВ КАТЕГОРИЙ */
.cp-head{padding:55px 0 25px}
.cp-h2{font-family:"Cormorant Garamond",Georgia,serif;font-weight:600;font-size:clamp(50px,3.4vw,25px);line-height:1.12;letter-spacing:.005em;color:#2a222b;margin:0}
.cp-h2 em{font-style:italic;font-weight:500;color:#ce2094}
.cp-sub{font-family:"Jost",system-ui,sans-serif;font-size:17px;color:#6d6269;margin:10px 0 0;max-width:60ch}


/* =========================================
   ПРОМО-БЛОК: СЕТКА И ПРОПОРЦИИ
   ========================================= */

/* Подключаем Cormorant Garamond с кириллицей */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&display=swap');

/* ============================================
   1. СЕТКА 5 БЛОКОВ (Десктоп)
   ============================================ */
@media (min-width: 1199px) {
    .swiper-partners .swiper-wrapper {
        display: grid !important;
        /* Левый блок 40%, правые делят остаток поровну */
        grid-template-columns: 40% 1fr 1fr !important; 
        grid-template-rows: 500px 500px !important;
        gap: 20px !important;
        transform: none !important;
        width: 100% !important;
    }

    /* Глушим инлайн-размеры и flex-свойства, которые ставит Swiper JS */
    .swiper-partners .swiper-slide {
        width: auto !important;
        max-width: none !important;
        flex: none !important;
        -ms-flex: none !important;
        margin: 0 !important;
        padding: 0 !important;
        height: auto !important;
    }

    /* 1-й блок: левая колонка, растянут на оба ряда */
    .swiper-partners .swiper-slide:nth-of-type(1) { grid-column: 1; grid-row: 1 / 3; }
    /* 2-5: сетка 2x2 справа */
    .swiper-partners .swiper-slide:nth-of-type(2) { grid-column: 2; grid-row: 1; }
    .swiper-partners .swiper-slide:nth-of-type(3) { grid-column: 3; grid-row: 1; }
    .swiper-partners .swiper-slide:nth-of-type(4) { grid-column: 2; grid-row: 2; }
    .swiper-partners .swiper-slide:nth-of-type(5) { grid-column: 3; grid-row: 2; }
    /* Шестой и далее не показываем */
    .swiper-partners .swiper-slide:nth-of-type(n+6) { display: none !important; }
}

/* Планшет и мобильные: swiper работает как классический слайдер */
@media (max-width: 1198px) {
    .swiper-partners .swiper-wrapper {
        display: flex !important; /* Возвращаем flex для корректной работы свайпа */
        gap: 20px;
    }
    .swiper-partners .swiper-slide {
        margin: 0 10px 20px 0 !important;
    }
}

/* ============================================
   2. БЛОК: белая рамка, скругление, Flex-структура
   ============================================ */
.partners__item {
    display: flex !important;
    flex-direction: column !important;
    background: #ffffff !important;
    border-radius: 24px !important;
    overflow: hidden !important;
    height: 100% !important;
    width: 100% !important;
    padding: 16px !important; /* Белая рамка вокруг картинки и текста */
    box-sizing: border-box !important;
    position: relative !important;
}

/* Планшет: фиксированная высота */
@media (max-width: 1198px) {
    .partners__item { height: 500px !important; }
}
/* Мобильные: ниже */
@media (max-width: 767px) {
    .partners__item { height: 400px !important; }
}

/* ============================================
   3. ИЗОБРАЖЕНИЕ: заполняет верхнюю часть, внутренние скругления
   ============================================ */
.partners__item-image {
    position: relative !important;
    flex: 1 1 auto !important; /* Занимает всё свободное пространство сверху */
    width: 100% !important;
    height: 100% !important;
    border-radius: 16px !important; /* Внутреннее скругление (создает эффект рамки) */
    overflow: hidden !important;
    z-index: 1 !important;
    background: #f4edf0; /* Цвет заглушки, пока картинка грузится */
}

.partners__item-image img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    display: block !important;
}

/* ============================================
   4. ТЕКСТ: белый фон снизу, сброс абсолютного позиционирования
   ============================================ */
.partners__item-desc {
    position: relative !important; /* КРИТИЧНО: Сбрасываем absolute из темы Простор */
    left: auto !important;
    right: auto !important;
    bottom: auto !important;
