/* ===== Брендовые токены Цветочной поэзии ===== */
:root{
--theme-primary-color:#ce2094;
--theme-secondary-color:#a81577;
--cp-bg:#f6f4f5;--cp-paper:#fdfcfd;--cp-ink:#2a222b;--cp-muted:#6d6269;
--cp-pink2:#eebed6;--cp-powder:#f2e3ec;--cp-plum:#6d4a63;
--cp-mint:#b3cebe;--cp-sage:#8ba58e;--cp-gd:#41584a;--cp-mintbg:#e9f2ec;
--cp-line:rgba(42,34,43,.14);
}
html{scroll-behavior:smooth}
body{background:var(--cp-bg);color:var(--cp-ink)}
::selection{background:var(--cp-pink2);color:var(--cp-ink)}
a:focus-visible,button:focus-visible,.ui-btn:focus-visible,input:focus-visible{outline:2px solid var(--cp-acc,#ce2094);outline-offset:2px}

/* ===== Типографика бренда ===== */
h1,h2,h3,h1 a,h2 a,h3 a{font-family:"Cormorant Garamond",Georgia,serif;color:var(--cp-ink)}

/* ===== Шапка (header v4) ===== */
.header{background:rgba(253,252,253,.96)}
.header__row--01{background:var(--cp-mintbg)}
.header__row--01 a,.header__call-btn mark{color:var(--cp-gd)}
.header__nav-menu>li>a{font-weight:500;color:var(--cp-ink)}
.header__nav-menu>li>a:hover{color:var(--cp-accd,#a81577)}
.header__catalog-btn{background:var(--cp-acc,#ce2094);border-radius:999px}

/* ===== Кнопки ===== */
.ui-btn--primary{background:var(--cp-acc,#ce2094);border-color:var(--cp-acc,#ce2094)}
.ui-btn--primary:hover{background:var(--cp-accd,#a81577);border-color:var(--cp-accd,#a81577)}

/* ===== Карточки товаров ===== */
.products__item{background:var(--cp-paper);border:1px solid var(--cp-line);border-radius:24px}

/* ===== Фирменные классы для HTML-блоков (текстовый блок, промо блок) ===== */
.cp-arch{border-radius:999px 999px 28px 28px;overflow:hidden}
.cp-hand{font-family:"Caveat",cursive;color:var(--cp-gd)}
.cp-quote{font-family:"Cormorant Garamond",Georgia,serif;font-style:italic;color:var(--cp-acc,#ce2094);border-left:3px solid var(--cp-mint);padding-left:22px}
.cp-chip{display:inline-block;border-radius:999px;background:var(--cp-powder);color:var(--cp-plum);padding:10px 20px;font-weight:500;margin:0 10px 10px 0}
.cp-chip:hover{background:var(--cp-acc,#ce2094);color:#fff}
.cp-mint-band{background:var(--cp-mintbg);border-radius:32px;padding:48px}
.cp-powder-band{background:var(--cp-powder);border-radius:32px;padding:48px}
.cp-marquee{background:var(--cp-powder);border-top:1px solid var(--cp-line);border-bottom:1px solid var(--cp-line);overflow:hidden;padding:14px 0}
.cp-marquee-track{display:flex;gap:48px;width:max-content;animation:cp-slide 32s linear infinite}
.cp-marquee span{display:flex;gap:48px;white-space:nowrap;font-family:"Cormorant Garamond",Georgia,serif;font-style:italic;font-size:18px;color:var(--cp-plum)}
@keyframes cp-slide{to{transform:translateX(-50%)}}
@media (prefers-reduced-motion:reduce){.cp-marquee-track{animation:none}}

/* ===== ПОДКЛЮЧЕНИЕ ШРИФТОВ ===== */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Jost:wght@400;500;600;700&family=Caveat:wght@500;600&display=swap');

/* ===== HERO СЕКЦИЯ ===== */
.cp-hero {
  position: relative;
  padding: 40px 0; /* Уменьшено с 80px до 40px */
  background: #f6f4f5;
  overflow: hidden;
}

.cp-hero .container {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 56px;
  align-items: center;
  padding: 0 80px; /* Увеличены боковые отступы */
  max-width: 1350px; /* Увеличена максимальная ширина */
  margin: 0 auto;
}

/* Явно задаем порядок для десктопа */
.cp-hero-content {
  order: 1;
}

.cp-hero-image-wrap {
  order: 2;
}

/* ===== ЗАГОЛОВОК ===== */
.cp-hero-title {
  font-family: 'Cormorant Garamond', Georgia, serif;
