  );
}

.cp-marquee__track {
  display: flex;
  width: max-content;
  will-change: transform;
  animation: cp-marquee-scroll 36s linear infinite;
}

.cp-marquee__content {
  display: flex;
  flex-shrink: 0;
  gap: 56px;                      /* расстояние между словами */
  align-items: center;
  list-style: none;
  margin: 0;
  padding: 0 28px;                /* половина от gap для идеального бесшовного стыка */
  counter-reset: marquee;
}

.cp-marquee__content li {
  display: inline-flex;
  align-items: center;
  gap: 12px;                      /* отступ между текстом и точкой */
  white-space: nowrap;
  font-family: 'Cormorant Garamond', serif;
  font-style: italic;
  font-size: 22px;
  font-weight: 600;
  line-height: 1.6;
  letter-spacing: normal;
  color: #6d4a63;                 /* сливовый */
}

/* Разделитель-точка между элементами */
.cp-marquee__content li:not(:last-child)::after {
  content: '';
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #6d4a63;            /* сливовый акцент */
  flex-shrink: 0;
}

/* Пауза при наведении */
.cp-marquee:hover .cp-marquee__track {
  animation-play-state: paused;
}

/* Keyframes: сдвигаем на -50% (один дубликат) для бесшовного цикла */
@keyframes cp-marquee-scroll {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ============================================
   Адаптив
   ============================================ */
@media (max-width: 768px) {
  .cp-marquee {
    padding: 14px 0;
    -webkit-mask-image: linear-gradient(
      to right,
      transparent 0,
      #000 24px,
      #000 calc(100% - 24px),
      transparent 100%
    );
    mask-image: linear-gradient(
      to right,
      transparent 0,
      #000 24px,
      #000 calc(100% - 24px),
      transparent 100%
    );
  }

  .cp-marquee__content {
    gap: 40px;
    padding: 0 20px;
  }

  .cp-marquee__content li {
    font-size: 16px;              /* адаптация для мобильных экранов */
    gap: 8px;
  }

  .cp-marquee__track {
    animation-duration: 24s;
  }
}

/* ============================================
   Respect prefers-reduced-motion
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  .cp-marquee__track {
    animation: none;
  }
  /* Показываем только один набор, чтобы не было дублей */
  .cp-marquee__content[aria-hidden="true"] {
    display: none;
  }
  .cp-marquee__track {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
  }
  .cp-marquee__track::-webkit-scrollbar {
    display: none;
  }
}
/* НАСТРОЙКА ЗАГОЛОВКОВ КАТЕГОРИЙ */
.cp-head{padding:55px 0 25px}
.cp-h2{font-family:"Cormorant Garamond",Georgia,serif;font-weight:600;font-size:clamp(50px,3.4vw,25px);line-height:1.12;letter-spacing:.005em;color:#2a222b;margin:0}
.cp-h2 em{font-style:italic;font-weight:500;color:#ce2094}
.cp-sub{font-family:"Jost",system-ui,sans-serif;font-size:17px;color:#6d6269;margin:10px 0 0;max-width:60ch}


/* =========================================
   ПРОМО-БЛОК: СЕТКА И ПРОПОРЦИИ
   ========================================= */

/* Подключаем Cormorant Garamond с кириллицей */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&display=swap');

/* ============================================
   1. СЕТКА 5 БЛОКОВ (Десктоп)
   ============================================ */
@media (min-width: 1199px) {
    .swiper-partners .swiper-wrapper {
        display: grid !important;
        /* Левый блок 40%, правые делят остаток поровну */
        grid-template-columns: 40% 1fr 1fr !important; 
        grid-template-rows: 500px 500px !important;
        gap: 20px !important;
        transform: none !important;
        width: 100% !important;
    }

    /* Глушим инлайн-размеры и flex-свойства, которые ставит Swiper JS */
    .swiper-partners .swiper-slide {
        width: auto !important;
        max-width: none !important;
        flex: none !important;
        -ms-flex: none !important;
        margin: 0 !important;
        padding: 0 !important;
        height: auto !important;
    }

    /* 1-й блок: левая колонка, растянут на оба ряда */
    .swiper-partners .swiper-slide:nth-of-type(1) { grid-column: 1; grid-row: 1 / 3; }
    /* 2-5: сетка 2x2 справа */
    .swiper-partners .swiper-slide:nth-of-type(2) { grid-column: 2; grid-row: 1; }
    .swiper-partners .swiper-slide:nth-of-type(3) { grid-column: 3; grid-row: 1; }
    .swiper-partners .swiper-slide:nth-of-type(4) { grid-column: 2; grid-row: 2; }
    .swiper-partners .swiper-slide:nth-of-type(5) { grid-column: 3; grid-row: 2; }
    /* Шестой и далее не показываем */
    .swiper-partners .swiper-slide:nth-of-type(n+6) { display: none !important; }
}

/* Планшет и мобильные: swiper работает как классический слайдер */
@media (max-width: 1198px) {
    .swiper-partners .swiper-wrapper {
        display: flex !important; /* Возвращаем flex для корректной работы свайпа */
        gap: 20px;
    }
    .swiper-partners .swiper-slide {
        margin: 0 10px 20px 0 !important;
    }
}

/* ============================================
   2. БЛОК: белая рамка, скругление, Flex-структура
   ============================================ */
.partners__item {
    display: flex !important;
    flex-direction: column !important;
    background: #ffffff !important;
    border-radius: 24px !important;
    overflow: hidden !important;
    height: 100% !important;
    width: 100% !important;
    padding: 16px !important; /* Белая рамка вокруг картинки и текста */
    box-sizing: border-box !important;
    position: relative !important;
}

/* Планшет: фиксированная высота */
@media (max-width: 1198px) {
    .partners__item { height: 500px !important; }
}
/* Мобильные: ниже */
@media (max-width: 767px) {
    .partners__item { height: 400px !important; }
}

/* ============================================
   3. ИЗОБРАЖЕНИЕ: заполняет верхнюю часть, внутренние скругления
   ============================================ */
.partners__item-image {
    position: relative !important;
    flex: 1 1 auto !important; /* Занимает всё свободное пространство сверху */
    width: 100% !important;
    height: 100% !important;
    border-radius: 16px !important; /* Внутреннее скругление (создает эффект рамки) */
    overflow: hidden !important;
    z-index: 1 !important;
    background: #f4edf0; /* Цвет заглушки, пока картинка грузится */
}

.partners__item-image img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    display: block !important;
}

/* ============================================
   4. ТЕКСТ: белый фон снизу, сброс абсолютного позиционирования
   ============================================ */
.partners__item-desc {
    position: relative !important; /* КРИТИЧНО: Сбрасываем absolute из темы Простор */
    left: auto !important;
    right: auto !important;
    bottom: auto !important;
    padding: 16px 8px 0 8px !important; /* Отступ от картинки до текста */
    background: transparent !important;
    z-index: 2 !important;
    display: flex !important;
    align-items: center !important;
    flex-shrink: 0 !important;
    min-height: 60px !important; /* Гарантированное место под текст */
}

/* ============================================
   5. ШРИФТ И ЦВЕТ ТЕКСТА
   ============================================ */
.partners__item-text,
.partners__item-title {
    font-family: 'Cormorant Garamond', Georgia, serif !important;
    color: #2a222b !important;
    font-size: 28px !important;
    line-height: 1.2 !important;
    font-weight: 600 !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 100%;
    margin: 0 !important;
}

/* Переопределяем белый текст от стандартного модификатора --white */
.partners__item--white .partners__item-text,
.partners__item--white .partners__item-title {
    color: #2a222b !important;
}


/* ===== Карточка товара в каталоге ===== */

/* 1. Убираем кнопки "Сравнение" и "Избранное" */
.products__item-buttons {
  display: none !important;
}

/* 2. Убираем статус наличия ("В наличии", "На складе") */
.products__item-status {
  display: none !important;
}

/* 3. Название товара — шрифт Cormorant Garamond */
.products__item-title {
  font-family: "Cormorant Garamond", Georgia, serif !important;
  font-size: 26px !important;
  font-weight: 700;
  line-height: 1.3;
}

/* 4. Изображение на всю ширину карточки */
/* ===== Картинка товара: во всю ширину, без смещения ===== */
.products__item-image{
  display:flex !important;
  align-items:center;
  justify-content:center;
  padding:0 !important;          /* убираем белые поля шаблона */
}
.products__item-image img{
  width:100% !important;
  height:100% !important;
  object-fit:cover;              /* заполняет блок целиком, без пустот */
  object-position:center;
  margin:0 !important;
}

/* ==== Слайдер: описание (1-я строка) ==== */
/* ==== Выравнивание влево (!important нужен: oc-slideshow/resizable
   перебивают desc более высокой специфичностью) ==== */
.intro__item,
.intro__item-desc{text-align:left !important}

/* ==== Горизонтальная плитка: влево + центр по высоте + высота ==== */
.intro__item{
  padding:0;
  align-items:center;
  min-height:16.7rem;
}

/* ==== Вертикальные плитки: влево + центр по высоте ==== */
.intro__item--vertical{
  justify-content:center;
  align-items:flex-start;
}
/* Картинку вертикальной плитки делаем обложкой,
   иначе шаблонный margin:auto 0 0 выталкивает текст вверх */
.intro__item--vertical .intro__item-image{
  position:absolute;top:0;left:0;
  width:100%;height:100%;
  margin:0;padding:0;z-index:1;
}
.intro__item--vertical .intro__item-image img{width:100%;height:100%;object-fit:cover}

/* ==== Контейнер текста ==== */
.intro__item:not(.intro__item--vertical) .intro__item-desc{
  flex:0 0 100%;max-width:100%;padding:3rem;
}
.intro__item--vertical .intro__item-desc{
  position:relative;z-index:2;
  flex:0 0 auto;width:100%;max-width:100%;
  padding:2.5rem 2rem;
}

/* ==== 1-я строка: крупная фуксия ==== */
.intro__item-category,
.intro__item-info{
  font-family:"Cormorant Garamond",Georgia,serif;
  font-size:3.6rem;font-weight:600;letter-spacing:.02em;
  color:#ce2094;opacity:1;
}
.intro__item-info{
  list-style:none;
  justify-content:flex-start !important; /* шаблон и --resizable центрируют li */
  margin:0 0 1.2rem;padding:0;
}

/* ==== 2-я строка ==== */
.intro__item-title{
  font-family:"Jost",system-ui,sans-serif;
  font-size:1.8rem;font-weight:500;line-height:1.3;
  color:#6d4a63;opacity:1;margin:0 0 2rem;
}

/* ==== Кнопка ==== */
.intro__item-price{
  background:#ce2094;color:#fff;border-radius:999px;
  font-family:"Jost",system-ui,sans-serif;font-weight:600;
  font-size:1.6rem;height:4.8rem;padding:1rem 2.8rem;
}
.intro__item-price:hover{background:#a81577}

/* ==== Мобильная версия ==== */
@media (max-width:767px){
  .intro__item-category,.intro__item-info{font-size:2.4rem}
  .intro__item-title{font-size:1.5rem}
  .intro__item:not(.intro__item--vertical) .intro__item-desc{padding:2.5rem 2rem}
}

/* ==== Скругление ==== */
.intro__item,.intro__swiper{border-radius:28px}

/* ==== Десктоп: пропорции колонок + правый слайдер ==== */
@media (min-width:1199px){
  .intro .col-xl-8{flex:0 0 38%;max-width:38%}
  .intro .col-xl-4{flex:0 0 62%;max-width:62%}
  /* !important только там, где Swiper пишет инлайном */
  .intro .js-swiper-intro .swiper-slide{width:100% !important}
  .intro .js-swiper-intro-right .swiper-wrapper{transform:none !important;gap:2rem}
  .intro .js-swiper-intro-right .swiper-slide{width:calc(50% - 1rem) !important}
  .intro .js-swiper-intro-right .swiper-pagination{display:none}
}


/* ==== Белый футер ==== */
.footer,
.is-footer-v2 .footer,
.is-footer-v3 .footer,
.is-footer-v4 .footer,
.is-footer-v5 .footer,
.is-footer-v6 .footer,
.is-footer-v7 .footer{
  background:#fff !important;
  color:#6d6269 !important;
}

/* Нижняя полоса футера тоже белая */
.is-footer-v3 .footer__bottom,
.is-footer-v4 .footer__bottom,
.is-footer-v5 .footer__bottom,
.is-footer-v6 .footer__bottom{
  background:#fff !important;
  color:#6d6269 !important;
  border-top:1px solid rgba(42,34,43,.14);
}

/* Заголовки колонок темные, ссылки серые с ховером в фуксию */
.footer__nav-title,
.footer__support-title,
.footer__caption{color:#2a222b !important;}
.footer__nav-link,
.footer__support-link,
.footer__support-phones,
.footer__call-btn{color:#6d6269 !important;}
.footer__nav-link:hover,
.footer__support-link:hover{color:#ce2094 !important;}

/* Плашка подписки и иконки оплат на белом */
.footer__subsc{background:#f2e3ec !important;}
.footer__payments>li{background:#f2e3ec !important;}

/* Если у вас темный вариант футера (v4-v6) - чиним поля подписки */
.is-footer-v4 .footer__subsc-form .ui-subsc .ui-input,
.is-footer-v5 .footer__subsc-form .ui-subsc .ui-input,
.is-footer-v6 .footer__subsc-form .ui-subsc .ui-input{
  background:#fff !important;
  border-color:#e4e7f1 !important;
  color:#343434 !important;
}
.is-footer-v4 .footer__subsc-form .ui-subsc .ui-check__text,
.is-footer-v5 .footer__subsc-form .ui-subsc .ui-check__text,
.is-footer-v6 .footer__subsc-form .ui-subsc .ui-check__text{color:#6d6269 !important;}". 

Надо оптимизировать коды блоков и перенести css в одно место, создать единый общий css.

Как лучше сделать - ты все сделаешь сразу (в этом случае мне нужно, чтобы ты отдельно по каждому блоку написал html код) или будем брать по одному блоку и исправлять шаг за шагом каждый?

content_list.content:
Отлично, начинаем **Шаг 1: Создание единого CSS-файла и базовой инфраструктуры**.

Этот шаг — фундамент. После него все последующие шаги будут простыми: просто переносим CSS из HTML-блоков в этот файл.

---

## 1.1. Создаём файл `custom.css` на хостинге

Зайдите в панель управления хостингом (Файловый менеджер) или подключитесь по FTP.

**Путь для создания файла:**
```
/catalog/view/theme/prostor/css/custom.css
```

Если папки `css` внутри `prostor` нет — создайте её. Сам файл пока оставляем пустым.

---

## 1.2. Редактируем `header.twig` — подключаем файл и шрифты

**Путь к файлу:**
```
/catalog/view/theme/prostor/template/common/header.twig
```

Найдите в этом файле последнюю строку `</head>`. **ПЕРЕД** ней вставьте следующий блок:

```html
{# === Preconnect: ускоряем загрузку шрифтов и иконок === #}
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="preconnect" href="https://unpkg.com" crossorigin>

{# === Подключение шрифтов (ВМЕСТО @import из CSS) === #}
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Jost:wght@400;500;600;700&family=Caveat:wght@500;600&display=swap">

{# === Иконки Phosphor === #}
<link rel="stylesheet" href="https://unpkg.com/@phosphor-icons/web@2.1.1/src/css/phosphor.css">

{# === Единый файл кастомных стилей Цветочной поэзии === #}
<link rel="stylesheet" href="catalog/view/theme/prostor/css/custom.css?v=20260828">
```

**Важно:** если где-то в `header.twig` уже есть `<link>` на Google Fonts или Phosphor — удалите их, чтобы не дублировать.

---

## 1.3. Заполняем `custom.css` — базовая структура

Откройте созданный файл `custom.css` и вставьте туда этот код:

```css
/* ============================================================
   ЦВЕТОЧНАЯ ПОЭЗИЯ · Единый CSS-файл
   Версия: 1.0
   ============================================================ */


/* === 1. БРЕНДОВЫЕ ПЕРЕМЕННЫЕ === */
:root {
    --theme-primary-color: #ce2094;
    --theme-secondary-color: #a81577;

    --cp-bg: #f6f4f5;
    --cp-paper: #fdfcfd;
    --cp-ink: #2a222b;
    --cp-muted: #6d6269;
    --cp-pink2: #eebed6;
    --cp-powder: #f2e3ec;
    --cp-plum: #6d4a63;
    --cp-mint: #b3cebe;
    --cp-sage: #8ba58e;
    --cp-gd: #41584a;
    --cp-mintbg: #e9f2ec;
    --cp-line: rgba(42, 34, 43, .14);

    --cp-acc: #ce2094;
    --cp-accd: #a81577;

    --font-display: "Cormorant Garamond", Georgia, serif;
    --font-body: "Jost", system-ui, sans-serif;
    --font-hand: "Caveat", cursive;
}


/* === 2. БАЗОВЫЕ ЭЛЕМЕНТЫ === */
html { scroll-behavior: smooth; }

body {
    background: var(--cp-bg);
    color: var(--cp-ink);
    font-family: var(--font-body);
}

::selection {
    background: var(--cp-pink2);
    color: var(--cp-ink);
}

a:focus-visible,
button:focus-visible,
.ui-btn:focus-visible,
input:focus-visible {
    outline: 2px solid var(--cp-acc);
    outline-offset: 2px;
}


/* === 3. ТИПОГРАФИКА БРЕНДА === */
h1, h2, h3,
h1 a, h2 a, h3 a {
    font-family: var(--font-display);
    color: var(--cp-ink);
}


/* === 4. ШАПКА (header v4) === */
.header { background: rgba(253, 252, 253, .96); }
.header__row--01 { background: var(--cp-mintbg); }
.header__row--01 a,
.header__call-btn mark { color: var(--cp-gd); }
.header__row--02 { min-height: 120px; }

.header__nav-menu > li > a {
    font-weight: 500;
    font-size: 1.3em;
    color: var(--cp-ink);
}

.header__nav-menu > li > a:hover {
    color: var(--cp-accd);
}

.header__search-compact-btn,
.header__acc-btn,
.header__action-btn,
.header__nav-action-btn,
.header__cart-btn,
.header__sticky-btn {
    color: var(--cp-ink);
}

.header__search-compact-btn svg,
.header__acc-btn svg,
.header__action-btn svg,
.header__nav-action-btn svg,
.header__cart-btn svg,
.header__sticky-btn svg {
    fill: currentColor !important;
}

.header__catalog-btn {
    background: var(--cp-acc);
    border-radius: 999px;
}


/* === 5. ЛОГОТИП === */
@media (min-width: 1199px) {
    .header__logo { height: 12rem !important; }
    .header__logo img,
    .header__logo svg {
        max-height: 10rem !important;
        max-width: 30rem !important;
        width: auto !important;
        height: auto !important;
    }
    .is-header-fixed .header-fixed .header__logo {
        height: 8rem !important;
        flex: 0 0 auto !important;
    }
    .is-header-fixed .header-fixed .header__logo img,
    .is-header-fixed .header-fixed .header__logo svg {
        max-height: 7rem !important;
        max-width: 30rem !important;
    }
}

@media (max-width: 1199px) {
    .header__mobile,
    .header__mobile-fixed { height: 10rem !important; }
    .header__logo img,
    .header__logo svg {
        max-height: calc(100% - 2rem) !important;
        max-width: 30rem !important;
        width: auto !important;
        height: auto !important;
    }
}


/* === 6. КОНТЕЙНЕРЫ === */
@media (min-width: 1199px) {
    .container,
    .container-fluid {
        max-width: 1350px !important;
    }
    .reviews-featured .container {
        max-width: 1000px !important;
    }
}


/* === 7. УБИРАЕМ ЛИШНЕЕ (Сравнение / Избранное) === */
a[href*="compare"],
.header__action-line,
.header__nav-action-line,
.products__item-buttons {
    display: none !important;
}

.header__action-btn[href*="wishlist"],
.header__action-btn:has(.icon-favorites) {
    display: none !important;
}


/* === 8. КНОПКИ === */
.ui-btn--primary {
    background: var(--cp-acc);
    border-color: var(--cp-acc);
