/* === 15. БЕГУЩАЯ СТРОКА (перенесена из пользовательских скриптов без изменений) === */
.cp-marquee {
    position: relative;
    width: 100%;
    overflow: hidden;
    background: #f2e3ec;
    border-top: 1px solid rgba(42, 34, 43, 0.14);
    border-bottom: 1px solid rgba(42, 34, 43, 0.14);
    padding: 16px 0;
    -webkit-mask-image: linear-gradient(to right, transparent 0, #000 80px, #000 calc(100% - 80px), transparent 100%);
    mask-image: linear-gradient(to right, transparent 0, #000 80px, #000 calc(100% - 80px), transparent 100%);
}

.cp-marquee__track {
    display: flex;
    width: max-content;
    will-change: transform;
    animation: cp-marquee-scroll 36s linear infinite;
}

.cp-marquee__content {
    display: flex;
    flex-shrink: 0;
    gap: 56px;
    align-items: center;
    list-style: none;
    margin: 0;
    padding: 0 28px;
}

.cp-marquee__content li {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    white-space: nowrap;
    font-family: 'Cormorant Garamond', serif;
    font-style: italic;
    font-size: 22px;
    font-weight: 600;
    line-height: 1.6;
    color: #6d4a63;
}

.cp-marquee__content li:not(:last-child)::after {
    content: '';
    display: inline-block;
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: #6d4a63;
    flex-shrink: 0;
}

.cp-marquee:hover .cp-marquee__track { animation-play-state: paused; }

@keyframes cp-marquee-scroll {
    from { transform: translateX(0); }
    to   { transform: translateX(-50%); }
}

@media (max-width: 768px) {
    .cp-marquee {
        padding: 14px 0;
        -webkit-mask-image: linear-gradient(to right, transparent 0, #000 24px, #000 calc(100% - 24px), transparent 100%);
        mask-image: linear-gradient(to right, transparent 0, #000 24px, #000 calc(100% - 24px), transparent 100%);
    }

    .cp-marquee__content {
        gap: 40px;
        padding: 0 20px;
    }

    .cp-marquee__content li {
        font-size: 16px;
        gap: 8px;
    }

    .cp-marquee__track { animation-duration: 24s; }
}

@media (prefers-reduced-motion: reduce) {
    .cp-marquee__track {
        animation: none;
        overflow-x: auto;
        -webkit-overflow-scrolling: touch;
        scrollbar-width: none;
    }

    .cp-marquee__content[aria-hidden="true"] { display: none; }
    .cp-marquee__track::-webkit-scrollbar { display: none; }
}
