/* 2. Убираем статус наличия ("В наличии", "На складе") */
.products__item-status {
  display: none !important;
}

/* 3. Название товара — шрифт Cormorant Garamond */
.products__item-title {
  font-family: "Cormorant Garamond", Georgia, serif !important;
  font-size: 26px !important;
  font-weight: 700;
  line-height: 1.3;
}

/* 4. Изображение на всю ширину карточки */
/* ===== Картинка товара: во всю ширину, без смещения ===== */
.products__item-image{
  display:flex !important;
  align-items:center;
  justify-content:center;
  padding:0 !important;          /* убираем белые поля шаблона */
}
.products__item-image img{
  width:100% !important;
  height:100% !important;
  object-fit:cover;              /* заполняет блок целиком, без пустот */
  object-position:center;
  margin:0 !important;
}

/* ==== Слайдер: описание (1-я строка) ==== */
/* ==== Выравнивание влево (!important нужен: oc-slideshow/resizable
   перебивают desc более высокой специфичностью) ==== */
.intro__item,
.intro__item-desc{text-align:left !important}

/* ==== Горизонтальная плитка: влево + центр по высоте + высота ==== */
.intro__item{
  padding:0;
  align-items:center;
  min-height:16.7rem;
}

/* ==== Вертикальные плитки: влево + центр по высоте ==== */
.intro__item--vertical{
  justify-content:center;
  align-items:flex-start;
}
/* Картинку вертикальной плитки делаем обложкой,
   иначе шаблонный margin:auto 0 0 выталкивает текст вверх */
.intro__item--vertical .intro__item-image{
  position:absolute;top:0;left:0;
  width:100%;height:100%;
  margin:0;padding:0;z-index:1;
}
.intro__item--vertical .intro__item-image img{width:100%;height:100%;object-fit:cover}

/* ==== Контейнер текста ==== */
.intro__item:not(.intro__item--vertical) .intro__item-desc{
  flex:0 0 100%;max-width:100%;padding:3rem;
}
.intro__item--vertical .intro__item-desc{
  position:relative;z-index:2;
  flex:0 0 auto;width:100%;max-width:100%;
  padding:2.5rem 2rem;
}

/* ==== 1-я строка: крупная фуксия ==== */
.intro__item-category,
.intro__item-info{
  font-family:"Cormorant Garamond",Georgia,serif;
  font-size:3.6rem;font-weight:600;letter-spacing:.02em;
  color:#ce2094;opacity:1;
}
.intro__item-info{
  list-style:none;
  justify-content:flex-start !important; /* шаблон и --resizable центрируют li */
  margin:0 0 1.2rem;padding:0;
}

/* ==== 2-я строка ==== */
.intro__item-title{
  font-family:"Jost",system-ui,sans-serif;
  font-size:1.8rem;font-weight:500;line-height:1.3;
  color:#6d4a63;opacity:1;margin:0 0 2rem;
}

/* ==== Кнопка ==== */
.intro__item-price{
  background:#ce2094;color:#fff;border-radius:999px;
  font-family:"Jost",system-ui,sans-serif;font-weight:600;
  font-size:1.6rem;height:4.8rem;padding:1rem 2.8rem;
}
.intro__item-price:hover{background:#a81577}

/* ==== Мобильная версия ==== */
@media (max-width:767px){
  .intro__item-category,.intro__item-info{font-size:2.4rem}
  .intro__item-title{font-size:1.5rem}
  .intro__item:not(.intro__item--vertical) .intro__item-desc{padding:2.5rem 2rem}
}

/* ==== Скругление ==== */
.intro__item,.intro__swiper{border-radius:28px}

/* ==== Десктоп: пропорции колонок + правый слайдер ==== */
@media (min-width:1199px){
  .intro .col-xl-8{flex:0 0 38%;max-width:38%}
  .intro .col-xl-4{flex:0 0 62%;max-width:62%}
  /* !important только там, где Swiper пишет инлайном */
  .intro .js-swiper-intro .swiper-slide{width:100% !important}
  .intro .js-swiper-intro-right .swiper-wrapper{transform:none !important;gap:2rem}
  .intro .js-swiper-intro-right .swiper-slide{width:calc(50% - 1rem) !important}
  .intro .js-swiper-intro-right .swiper-pagination{display:none}
}


/* ==== Белый футер ==== */
.footer,
.is-footer-v2 .footer,
.is-footer-v3 .footer,
.is-footer-v4 .footer,
.is-footer-v5 .footer,
.is-footer-v6 .footer,
.is-footer-v7 .footer{
  background:#fff !important;
  color:#6d6269 !important;
}

/* Нижняя полоса футера тоже белая */
.is-footer-v3 .footer__bottom,
.is-footer-v4 .footer__bottom,
.is-footer-v5 .footer__bottom,
.is-footer-v6 .footer__bottom{
  background:#fff !important;
  color:#6d6269 !important;
  border-top:1px solid rgba(42,34,43,.14);
}

/* Заголовки колонок темные, ссылки серые с ховером в фуксию */
.footer__nav-title,
.footer__support-title,
.footer__caption{color:#2a222b !important;}
.footer__nav-link,
.footer__support-link,
.footer__support-phones,
.footer__call-btn{color:#6d6269 !important;}
.footer__nav-link:hover,
.footer__support-link:hover{color:#ce2094 !important;}

/* Плашка подписки и иконки оплат на белом */
.footer__subsc{background:#f2e3ec !important;}
.footer__payments>li{background:#f2e3ec !important;}

/* Если у вас темный вариант футера (v4-v6) - чиним поля подписки */
.is-footer-v4 .footer__subsc-form .ui-subsc .ui-input,
.is-footer-v5 .footer__subsc-form .ui-subsc .ui-input,
.is-footer-v6 .footer__subsc-form .ui-subsc .ui-input{
  background:#fff !important;
  border-color:#e4e7f1 !important;
  color:#343434 !important;
}
.is-footer-v4 .footer__subsc-form .ui-subsc .ui-check__text,
.is-footer-v5 .footer__subsc-form .ui-subsc .ui-check__text,
.is-footer-v6 .footer__subsc-form .ui-subsc .ui-check__text{color:#6d6269 !important;}"?

content_list.content:
Хорошо, что инлайн-тест сработал — он дал точный ответ на вопрос, где обрыв. Теперь честный разбор.

## Что доказал тест

Инлайн-стиль применяется всегда, поверх любого CSS. Раз он сработал, значит:
- элемент и класс `.ct-band` — те самые, мы правим правильный блок;
- а правило `.ct-band` из `custom.css` **до браузера не доходит вообще**. Иначе вы бы увидели зазор ещё при старых 64px.

При этом блоки 14–23 (планка преимуществ, чипсы, галерея, карта, аккордеон) отрисованы стилями из `custom.css` — значит, файл подключён и парсится **вплоть до секции 23**. Обрыв ровно на границе: секция 24 либо **не сохранена в файле на сервере**, либо попала в файл после синтаксической поломки (незакрытая скобка или оборванный комментарий в конце секции 23), и браузер её «проглатывает».

## Моя часть ответственности

Код секции 24 в Шаге 12 был синтаксически верный, и селектор `.ct-band` совпадает с разметкой. Но я допустил методическую ошибку: в Шаге 12 я не заложил проверку, что секция доехала до браузера, а в шаге «увеличить отступ» я начал с правки значения, а не с диагностики. Если правила нет в файле, правка его значения действительно ничего не меняет — вы это и увидели. Надо было сразу смотреть Response файла. Признаю, это мой промах в последовательности действий.

Гипотеза про «Пользовательские скрипты» окончательно снята: там нет ни одного правила для `.ct-band`, они физически не могли задавить отступ.

## Решение одним заходом

**1. Сейчас, мгновенно** — расширьте инлайн, чтобы появился и нижний зазор:

```html
<div class="container-fluid ct-band" style="padding-top:100px;padding-bottom:80px">
```

**2. Лечение причины.** Откройте `custom.css` в файловом менеджере хостинга и прокрутите в самый конец.
- Если файл заканчивается секцией 23 (последние строки — `@media (prefers-reduced-motion: reduce) { .faqb-ico { transition: none; } }`) — секции 24 в файле нет. Допишите в конец файл целиком блок ниже.
- Если секция 24 на месте — значит выше неё поломка синтаксиса; пришлите последние 40–50 строк файла, я укажу точное место.

**Финальная секция 24 (с новыми отступами 100 сверху / 80 снизу):**

```css
/* === 24. СВЯЖИТЕСЬ С НАМИ (ct-) === */
.ct-band { padding: 100px 0 80px; }

.ct-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 32px;
    text-align: center;
}

.ct-col svg {
    width: 30px;
    height: 30px;
    color: var(--cp-acc);
}

.ct-col b {
    display: block;
    font-family: var(--font-display);
    font-weight: 600;
    font-size: 22px;
    line-height: 1.2;
    color: var(--cp-ink);
    margin: 14px 0 6px;
}

.ct-col b a {
    color: inherit;
    text-decoration: none;
    transition: color .2s;
}

.ct-col b a:hover { color: var(--cp-acc); }

.ct-col span {
    display: block;
    font-family: var(--font-body);
    font-size: 14px;
    color: var(--cp-muted);
}

.ct-line {
    border: 0;
    border-top: 1px solid var(--cp-line);
    margin: 44px 0 40px;
}

.ct-actions {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
}

.ct-btn {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    border-radius: 999px;
    font-family: var(--font-body);
    font-weight: 600;
    font-size: 15px;
    padding: 14px 28px;
    text-decoration: none;
    transition: transform .2s, background .2s, color .2s;
}

.ct-btn:active { transform: scale(.98); }

.ct-btn--primary {
    background: var(--cp-acc);
    color: #fff;
    box-shadow: 0 12px 28px -12px rgba(206, 32, 148, .5);
}

.ct-btn--primary:hover {
    background: var(--cp-accd);
    transform: translateY(-1px);
}

.ct-btn--primary i { font-size: 16px; }

.ct-btn--soft {
    background: var(--cp-powder);
    color: var(--cp-plum);
}

.ct-btn--soft:hover {
    background: var(--cp-acc);
    color: #fff;
    transform: translateY(-1px);
}

.ct-btn svg {
    width: 18px;
    height: 18px;
}

@media (max-width: 768px) {
    .ct-band { padding: 64px 0 56px; }
    .ct-grid { grid-template-columns: 1fr; gap: 26px; }
    .ct-line { margin: 32px 0; }
}
```

**3.** Сохраните файл, поднимите версию в `header.twig` до `?v=15`, сбросьте кэш, откройте с Ctrl+F5.

**4.** Проверка доставки: F12 → Network → `custom.css` → Response → поиск `ct-band`. Строки на месте — правило доехало. После этого **удалите инлайн-стиль** из HTML блока 16 (он больше не нужен, а без него мобильная версия получит свои аккуратные 64/56px из медиазапроса).

Напишите, чем заканчивался файл на сервере — по этому ответу поймём, была ли это несохранённая секция или поломка синтаксиса, и закроем Шаг 12 полностью.

Спасибо за скриншот — он дал точный ответ. Смотрите, что там видно:

## Что показывает DevTools

В панели **Styles** справа отображаются только те правила, которые браузер реально применил к элементу. Для вашего `.ct-band` видны **только** два правила:
- `.container-fluid { max-width: 1350px !important }` — из секции 7 нашего custom.css
- `.container { width: 100%; max-width: 1240px; ... }` — из секции 14

**А правила `.ct-band { padding: 100px 0 72px }` в панели Styles НЕТ ВООБЩЕ.**

Это значит: браузер не видит секцию 24. Физически. Она не попала в файл, который отдал сервер.

## Три причины и как проверить

**Причина 1. Файл на сервере не содержит секцию 24.**
Самое вероятное: при сохранении последние строки «отвалились» (файловый менеджер хостинга иногда обрезает длинные вставки, либо не было нажато «Сохранить»).

**Проверка (1 минута):**
1. Зайдите в файловый менеджер хостинга.
2. Откройте файл `catalog/view/theme/prostore/css/custom.css`.
3. Прокрутите в **самый низ**.
4. Последняя секция файла должна быть **24. СВЯЖИТЕСЬ С НАМИ (ct-)**, заканчивающаяся строками:
```css
@media (max-width: 768px) {
.ct-band { padding: 64px 0 56px; }
.ct-grid { grid-template-columns: 1fr; gap: 26px; }
.ct-line { margin: 32px 0; }
}
```
5. Если файла заканчивается на секции 23 — значит, секция 24 не сохранилась. Скопируйте блок секции 24 (полный текст я дам ниже) и вставьте в конец файла. Сохраните.

**Причина 2. Файл сохранён, но браузер использует старую закэшированную версию.**
В `header.twig` у вас сейчас `custom.css?v=13` (или другой номер). Браузер помнит старый файл с этим номером и не переспрашивает сервер.

**Решение:**
1. В `header.twig` поднимите версию до `?v=99` (просто большое число — чтобы гарантированно сбросить кэш).
2. Сохраните `header.twig`.
3. В админке OpenCart: **Система → Модификаторы → кнопка «Обновить»** (круговая стрелка) + очистите кэш темы в настройках разработчика «Простора».
4. Откройте сайт с **Ctrl + F5**.

**Причина 3. Синтаксическая ошибка в секции 23 «съела» секцию 24.**
Маловероятно, но возможно, если вы вносили правки вручную.

**Проверка:**
Откройте файл на сервере, найдите секцию 23 (ЧАСТЫЕ ВОПРОСЫ) и посмотрите на её конец. Последние строки должны быть:
```css
@media (prefers-reduced-motion: reduce) {
.faqb-ico { transition: none; }
}
```
Если после этого идёт секция 24 — всё в порядке. Если что-то обрезано или есть лишние/незакрытые скобки — пришлите хвост файла, я укажу точное место.

## Готовый блок секции 24 (если нужно добавить)

```css
/* === 24. СВЯЖИТЕСЬ С НАМИ (ct-) === */
.ct-band { padding: 100px 0 80px; }
.ct-grid {
display: grid;
grid-template-columns: repeat(3, 1fr);
gap: 32px;
text-align: center;
}
.ct-col svg {
width: 30px;
height: 30px;
color: var(--cp-acc);
}
.ct-col b {
display: block;
font-family: var(--font-display);
font-weight: 600;
font-size: 22px;
line-height: 1.2;
color: var(--cp-ink);
margin: 14px 0 6px;
}
.ct-col b a {
color: inherit;
text-decoration: none;
transition: color .2s;
}
.ct-col b a:hover { color: var(--cp-acc); }
.ct-col span {
display: block;
font-family: var(--font-body);
font-size: 14px;
color: var(--cp-muted);
}
.ct-line {
border: 0;
border-top: 1px solid var(--cp-line);
margin: 44px 0 40px;
}
.ct-actions {
display: flex;
justify-content: center;
align-items: center;
gap: 14px;
flex-wrap: wrap;
}
.ct-btn {
display: inline-flex;
align-items: center;
gap: 10px;
border-radius: 999px;
font-family: var(--font-body);
font-weight: 600;
font-size: 15px;
padding: 14px 28px;
text-decoration: none;
transition: transform .2s, background .2s, color .2s;
}
.ct-btn:active { transform: scale(.98); }
.ct-btn--primary {
background: var(--cp-acc);
color: #fff;
box-shadow: 0 12px 28px -12px rgba(206, 32, 148, .5);
}
.ct-btn--primary:hover {
background: var(--cp-accd);
transform: translateY(-1px);
}
.ct-btn--primary i { font-size: 16px; }
.ct-btn--soft {
background: var(--cp-powder);
color: var(--cp-plum);
}
.ct-btn--soft:hover {
background: var(--cp-acc);
color: #fff;
transform: translateY(-1px);
}
.ct-btn svg {
width: 18px;
height: 18px;
}
@media (max-width: 768px) {
.ct-band { padding: 64px 0 56px; }
.ct-grid { grid-template-columns: 1fr; gap: 26px; }
.ct-line { margin: 32px 0; }
}
```

## Финальный чек-лист

1. **Проверьте файл на сервере** — есть ли в нём секция 24. Если нет — вставьте код выше в конец файла, сохраните.
2. **В `header.twig`** поставьте `custom.css?v=99`.
3. **Сбросьте кэш**: Модификаторы → Обновить + кэш темы + (если есть) кнопка «Сбросить кэш» в настройках Простора.
4. Откройте сайт с **Ctrl + F5**.
5. Снова откройте DevTools → Elements → кликните на `.ct-band` → в панели Styles справа **должно появиться** правило `.ct-band { padding: 100px 0 80px }`. Если появилось — отступ будет виден на странице.

Напишите результат проверки файла на сервере — есть там секция 24 или нет. Это даст окончательный ответ.

Принято, это финальный шаг проекта. Его суть: переносим в `custom.css` последние три раздела из «Пользовательских скриптов» (промо-блок, слайдер intro, белый футер), затем полностью опустошаем это поле. После этого весь кастомный CSS сайта живёт в одном файле, и «двухголовость» исчезает.

Важно: сейчас правила из пользовательских скриптов загружаются **после** файлов темы и перебивают их. Чтобы перенос ничего не сломал, сначала убеждаемся, что `custom.css` подключён в правильном месте.

---

## 13.0. Проверка header.twig (обязательное условие)

Откройте `header.twig`. Если наш блок ссылок всё ещё стоит **до** тега `<head>` (как в присланном вами файле), перенесите его: удалите четыре ссылки с комментариями из шапки и вставьте перед `</head>`:

```html
{# === Предзагрузка Hero-изображения и главного шрифта === #}
<link rel="preload" as="image" href="catalog/view/theme/prostore/image/hero.webp" fetchpriority="high">
<link rel="preload" href="catalog/view/theme/prostore/fonts/cormorant-garamond/CormorantGaramond-SemiBold.woff2" as="font" type="font/woff2" crossorigin>
{# === Иконки Phosphor === #}
<link rel="stylesheet" href="https://unpkg.com/@phosphor-icons/web@2.1.1/src/css/phosphor.css">
{# === Единый файл кастомных стилей (последним, после темы) === #}
<link rel="stylesheet" href="catalog/view/theme/prostore/css/custom.css?v=101">
```

Если вы уже сделали это раньше — просто поднимите версию до `?v=101`.

---

## 13.1. Правка заголовков секций в custom.css

Сейчас вживую заголовки `.cp-h2` рендерятся размером 50px на всех экранах (в пользовательских скриптах был «сломанный» clamp, который всегда возвращал 50px, и он перебивал наш). После очистки поля включится наш clamp, и на мобильных заголовок уменьшится до 32px — это изменение вида, которого мы не хотим. Поэтому в секции 12 замените строку:

```css
    font-size: clamp(32px, 3.4vw, 50px);
```

на:

```css
    font-size: 50px;
```

Если позже захотите аккуратные заголовки на мобильных — добавим один медиазапрос, скажете.

---

## 13.2. Добавляем в конец custom.css три раздела

Rem-значения intro конвертированы по базе шаблона 10px (16.7rem = 167px и т.д.) — визуальные значения сохранены.

```css
/* === 25. ПРОМО-БЛОК: СЕТКА 5 БЛОКОВ (swiper-partners) === */
@media (min-width: 1199px) {
    .swiper-partners .swiper-wrapper {
        display: grid !important;
        grid-template-columns: 40% 1fr 1fr !important;
        grid-template-rows: 500px 500px !important;
        gap: 20px !important;
        transform: none !important;
        width: 100% !important;
    }

    .swiper-partners .swiper-slide {
