    }
}

.cats-item {
    display: flex;
    flex-direction: column;
    background: #ffffff;
    border-radius: 24px;
    overflow: hidden;
    padding: 16px;
    box-sizing: border-box;
    text-decoration: none;          /* убираем подчёркивание ссылки */
    color: var(--cp-ink);           /* убираем синий цвет ссылки */
    transition: transform .3s, box-shadow .3s;
}

/* Фирменная анимация при наведении */
.cats-item:hover {
    transform: translateY(-4px);
    box-shadow: 0 20px 40px -18px rgba(42, 34, 43, .16);
}

.cats-media {
    flex: 1 1 auto;
    border-radius: 16px;
    overflow: hidden;
    background: #f4edf0;
}

.cats-media img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.cats-title {
    flex-shrink: 0;
    min-height: 60px;
    display: flex;
    align-items: center;
    padding: 16px 8px 0;
