  margin: 0 0 24px 0;
  letter-spacing: 0.005em;
}

/* Курсивный акцент в заголовке */
.cp-hero-title em {
  font-style: italic;
  font-weight: 500;
  color: #ce2094;
  padding-bottom: 0.08em;
}

/* ===== ПОДЗАГОЛОВОК ===== */
.cp-hero-subtitle {
  font-family: 'Jost', sans-serif;
  font-size: 17px;
  font-weight: 400;
  line-height: 1.6;
  color: #6d6269;
  margin: 0 0 32px 0;
  max-width: 480px;
}

/* ===== КНОПКИ ===== */
.cp-hero-buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Основная кнопка "Выбрать букет" */
.cp-btn-primary {
