/* ===== СТИЛИЗАЦИЯ БЛОКА ПРЕИМУЩЕСТВ ===== */
.benefits {
    padding: 4rem 0;
    background: var(--color-2);
    overflow: hidden;
}

.benefits__marquee {
    position: relative;
    display: flex;
    overflow: hidden;
    user-select: none;
}

.benefits__track {
    display: flex;
    gap: 4rem;
    animation: scroll 30s linear infinite;
    flex-shrink: 0;
