/* ===== ПОДКЛЮЧЕНИЕ ШРИФТОВ ===== */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Jost:wght@400;500;600;700&family=Caveat:wght@500;600&display=swap');

/* ===== HERO СЕКЦИЯ ===== */
.cp-hero {
  position: relative;
  padding: 40px 0; /* Уменьшено с 80px до 40px */
  background: #f6f4f5;
  overflow: hidden;
}

.cp-hero .container {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 56px;
  align-items: center;
  padding: 0 80px; /* Увеличены боковые отступы */
  max-width: 1350px; /* Увеличена максимальная ширина */
  margin: 0 auto;
}

/* Явно задаем порядок для десктопа */
.cp-hero-content {
  order: 1;
}

.cp-hero-image-wrap {
  order: 2;
}

/* ===== ЗАГОЛОВОК ===== */
.cp-hero-title {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 64px;
  font-weight: 600;
  line-height: 1.08;
  color: #2a222b;
  margin: 0 0 24px 0;
  letter-spacing: 0.005em;
}

/* Курсивный акцент в заголовке */
.cp-hero-title em {
  font-style: italic;
  font-weight: 500;
  color: #ce2094;
  padding-bottom: 0.08em;
}

/* ===== ПОДЗАГОЛОВОК ===== */
.cp-hero-subtitle {
  font-family: 'Jost', sans-serif;
  font-size: 17px;
  font-weight: 400;
  line-height: 1.6;
  color: #6d6269;
  margin: 0 0 32px 0;
  max-width: 480px;
}

/* ===== КНОПКИ ===== */
.cp-hero-buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Основная кнопка "Выбрать букет" */
.cp-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 16px 32px;
  background: #ce2094;
  color: #ffffff;
  font-family: 'Jost', sans-serif;
  font-size: 16px;
  font-weight: 600;
  text-decoration: none;
  border-radius: 999px;
  border: 2px solid #ce2094;
  transition: all 0.2s ease;
  box-shadow: 0 12px 28px -12px rgba(206, 32, 148, 0.5);
}

.cp-btn-primary:hover {
  background: #a81577;
  border-color: #a81577;
  transform: translateY(-2px);
  box-shadow: 0 16px 32px -12px rgba(206, 32, 148, 0.6);
  color: #ffffff;
  text-decoration: none;
}

/* Вторичная кнопка "Условия доставки" */
.cp-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 16px 32px;
  background: #f2e3ec;
  color: #6d4a63;
  font-family: 'Jost', sans-serif;
  font-size: 16px;
  font-weight: 600;
  text-decoration: none;
  border-radius: 999px;
  border: 2px solid transparent;
  transition: all 0.2s ease;
}

.cp-btn-secondary:hover {
  background: #ce2094;
  color: #ffffff;
  transform: translateY(-2px);
  text-decoration: none;
}

/* ===== АРХ-ИЗОБРАЖЕНИЕ ===== */
.cp-hero-image-wrap {
  position: relative;
  max-width: 480px; /* Ограничена максимальная ширина изображения */
  margin-left: auto; /* Центрирование */
}

.cp-arch {
  border-radius: 999px 999px 28px 28px;
  overflow: hidden;
  aspect-ratio: 4/5;
  box-shadow: 0 20px 40px -18px rgba(42, 34, 43, 0.16);
}

.cp-arch img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ===== РУКОПИСНАЯ ПОДПИСЬ ===== */
.cp-handwritten {
  position: absolute;
  left: 8px;
  bottom: -10px;
  transform: rotate(-4deg);
  font-family: 'Caveat', cursive;
  font-size: 22px;
  font-weight: 500;
  color: #41584a;
  background: #ffffff;
  padding: 8px 16px;
  border-radius: 999px;
  box-shadow: 0 4px 12px -4px rgba(0, 0, 0, 0.1);
  z-index: 10;
}

/* ===== АДАПТИВ ===== */
@media (max-width: 1199px) {
  .cp-hero .container {
    padding: 0 50px; /* Адаптивные боковые отступы */
  }
}

@media (max-width: 991px) {
  .cp-hero {
    padding: 32px 0; /* Ещё меньше на планшетах */
  }

  .cp-hero .container {
    grid-template-columns: 1fr;
    gap: 40px;
    padding: 0 24px;
  }

  .cp-hero-title {
    font-size: 48px;
  }

  .cp-hero-image-wrap {
    order: -1; /* На мобильном изображение сверху */
    max-width: 360px; /* Меньше изображение на планшетах */
    margin: 0 auto;
  }

  .cp-hero-content {
    order: 2; /* На мобильном текст снизу */
  }
}

@media (max-width: 575px) {
  .cp-hero {
    padding: 24px 0; /* Минимальные отступы на мобильных */
  }

  .cp-hero .container {
    padding: 0 16px;
  }

  .cp-hero-title {
    font-size: 36px;
  }

  .cp-hero-subtitle {
    font-size: 15px;
  }

  .cp-btn-primary,
  .cp-btn-secondary {
    padding: 14px 24px;
    font-size: 15px;
  }

  .cp-hero-image-wrap {
    max-width: 280px; /* Ещё меньше на мобильных */
  }
}



