/* ==== Слайдер: описание (1-я строка) ==== */
/* ==== Выравнивание влево (!important нужен: oc-slideshow/resizable
   перебивают desc более высокой специфичностью) ==== */
.intro__item,
.intro__item-desc{text-align:left !important}

/* ==== Горизонтальная плитка: влево + центр по высоте + высота ==== */
.intro__item{
  padding:0;
  align-items:center;
  min-height:16.7rem;
}

/* ==== Вертикальные плитки: влево + центр по высоте ==== */
.intro__item--vertical{
  justify-content:center;
  align-items:flex-start;
}
/* Картинку вертикальной плитки делаем обложкой,
   иначе шаблонный margin:auto 0 0 выталкивает текст вверх */
.intro__item--vertical .intro__item-image{
  position:absolute;top:0;left:0;
  width:100%;height:100%;
  margin:0;padding:0;z-index:1;
}
.intro__item--vertical .intro__item-image img{width:100%;height:100%;object-fit:cover}

/* ==== Контейнер текста ==== */
.intro__item:not(.intro__item--vertical) .intro__item-desc{
  flex:0 0 100%;max-width:100%;padding:3rem;
}
.intro__item--vertical .intro__item-desc{
  position:relative;z-index:2;
  flex:0 0 auto;width:100%;max-width:100%;
  padding:2.5rem 2rem;
}

