.dlv-ring {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 46px;
    height: 46px;
    border-radius: 50%;
    border: 2px solid rgba(206, 32, 148, .45);
    transform: translate(-50%, -50%) scale(1);
