}


/* === 26. СЛАЙДЕР INTRO (rem конвертирован по базе 10px) === */
.intro__item,
.intro__item-desc { text-align: left !important; }

.intro__item {
    padding: 0;
    align-items: center;
    min-height: 167px; /* раньше 16.7rem */
}

.intro__item--vertical {
    justify-content: center;
    align-items: flex-start;
}

.intro__item--vertical .intro__item-image {
    position: absolute;
    top: 0;
